// questions-extra.js — Extended bank (added to the base bank)
// Domain 1 (ids 101-130), Domain 2 (201-225), Domain 3 (301-325), Domain 4 (401-420)
QUESTIONS.push(
  {"id": 101, "domain": 1, "q": "A company hosts a web application on EC2 instances behind an Application Load Balancer. The application must read objects from an S3 bucket. The developers currently hardcode IAM access keys in the application code. Which solution is the MOST secure way to grant access to S3?", "options": ["Store the access keys in an encrypted configuration file on the EC2 instance", "Attach an IAM role to the EC2 instances with a policy that allows access to the S3 bucket", "Create a dedicated IAM user and distribute its keys through Systems Manager", "Use the root account to generate temporary access keys every hour"], "correct": 1, "explanation": "An IAM role attached to the EC2 instance provides temporary credentials that are automatically rotated through the metadata service, eliminating any plaintext secret. Hardcoding or storing keys (options A and C) exposes long-lived credentials, and using the root account (option D) violates the principle of least privilege."},
  {"id": 102, "domain": 1, "q": "A healthcare company must encrypt sensitive medical data in S3 and requires full control over key rotation as well as an audit trail of every cryptographic call through CloudTrail. Which encryption option BEST meets these requirements?", "options": ["SSE-S3 (S3-managed keys)", "SSE-KMS with a customer managed key (CMK)", "Client-side encryption without KMS", "SSE-C (customer-provided keys)"], "correct": 1, "explanation": "SSE-KMS with a CMK lets you define the rotation policy, control permissions through the key policy, and log every use of the key in CloudTrail. SSE-S3 provides no granular control or audit, and SSE-C forces the client to manage and transmit the key with each request without native CloudTrail integration."},
  {"id": 103, "domain": 1, "q": "A company has an AWS Organization with multiple accounts. The security team wants to ensure that no member account can disable CloudTrail, regardless of the IAM permissions granted locally within those accounts. Which approach should they use?", "options": ["Attach an IAM deny policy to all users in each account", "Create a Service Control Policy (SCP) at the OU level that denies the actions to disable CloudTrail", "Enable MFA on all member account root users", "Configure a NACL that blocks access to the CloudTrail API"], "correct": 1, "explanation": "An SCP defines the maximum permissions boundary for member accounts and applies even to local administrators, ensuring that no entity can disable CloudTrail. Local IAM policies (option A) can be modified by account admins, MFA does not restrict API actions, and NACLs operate at the network layer, not on API authorizations."},
  {"id": 104, "domain": 1, "q": "An application needs to retrieve a database password that must be automatically rotated every 30 days, with native integration for RDS. Which AWS service BEST meets this need?", "options": ["Systems Manager Parameter Store (standard String parameter)", "AWS Secrets Manager", "AWS KMS", "S3 with SSE-KMS encryption"], "correct": 1, "explanation": "Secrets Manager supports automatic rotation of secrets through built-in Lambda functions, including for RDS, which directly meets the requirement. Standard Parameter Store does not provide native automatic rotation, and KMS/S3 are not secrets managers with rotation."},
  {"id": 105, "domain": 1, "q": "A company wants to automatically detect malicious or unauthorized behavior in its AWS environment, such as anomalous API calls, communication with known malicious IP addresses, or cryptocurrency mining, by analyzing VPC Flow Logs, DNS logs, and CloudTrail. Which service should it enable?", "options": ["Amazon Macie", "Amazon Inspector", "Amazon GuardDuty", "AWS Security Hub"], "correct": 2, "explanation": "GuardDuty is the threat detection service that continuously analyzes VPC Flow Logs, DNS logs, and CloudTrail to identify suspicious activity. Macie targets the discovery of sensitive data (PII), Inspector assesses workload vulnerabilities, and Security Hub aggregates findings without performing this behavioral detection itself."},
  {"id": 106, "domain": 1, "q": "A company wants to allow users in a development AWS account (account B) to access an S3 bucket located in the production account (account A), without creating IAM users in account A. Which approach is recommended?", "options": ["Share the access keys of an IAM user from account A with account B", "Create an IAM role in account A with a trust relationship that allows account B to assume it, then use sts:AssumeRole", "Make the S3 bucket public and filter by IP address", "Enable Block Public Access and copy the objects to account B"], "correct": 1, "explanation": "The recommended cross-account pattern is to create an IAM role in account A whose trust policy allows account B, with account B users then calling sts:AssumeRole to obtain temporary credentials. Sharing keys (A) is insecure, making the bucket public (C) creates major exposure, and copying the objects (D) does not address the need for direct access."},
  {"id": 107, "domain": 1, "q": "An application deployed in private subnets must access DynamoDB without the traffic traversing the internet, and the company wants to avoid the cost of a NAT Gateway for this access. Which solution should it implement?", "options": ["A Gateway VPC endpoint for DynamoDB", "An Interface VPC endpoint (PrivateLink) for DynamoDB", "A NAT Gateway in a public subnet", "An Internet Gateway attached to the VPC"], "correct": 0, "explanation": "DynamoDB and S3 are accessible through Gateway endpoints, which add a route to the route table and are free, keeping traffic on the AWS network. Interface endpoints (option B) do exist for DynamoDB (PrivateLink) but are billed per hour and per GB, so they do not meet the cost requirement, while a NAT Gateway and Internet Gateway would route traffic out to the internet at additional cost."},
  {"id": 108, "domain": 1, "q": "A security team finds that Security Groups associated with database instances allow port 3306 from 0.0.0.0/0. They want to restrict access only to the application instances. Which configuration BEST applies the principle of least privilege?", "options": ["Allow port 3306 from the entire VPC CIDR", "Allow port 3306 with the source set to the Security Group of the application instances", "Add a NACL rule denying all outbound traffic from the database", "Allow port 3306 from the public IP address of the Load Balancer"], "correct": 1, "explanation": "Referencing the Security Group of the application instances as the source in the database SG rule restricts access to only the application instances, following least privilege. The entire VPC CIDR (A) is too broad, an outbound NACL (C) does not address the inbound opening, and the Load Balancer IP (D) does not match the actual application flow to the database."},
  {"id": 109, "domain": 1, "q": "A company must protect its web application exposed through an Application Load Balancer against common application-layer attacks such as SQL injection and cross-site scripting (XSS). Which AWS service should it deploy?", "options": ["AWS Shield Standard", "AWS WAF with managed rules", "Amazon GuardDuty", "Custom Network ACLs"], "correct": 1, "explanation": "AWS WAF filters HTTP/HTTPS traffic at layer 7 and offers managed rules against SQL injection and XSS, which can be attached to an ALB. Shield Standard protects against DDoS attacks (layers 3/4), GuardDuty detects threats but does not filter traffic, and NACLs operate at the network layer without application inspection."},
  {"id": 110, "domain": 1, "q": "A company wants to automatically discover and classify personally identifiable information (PII) stored in its S3 buckets in order to comply with regulatory requirements. Which service is designed for this?", "options": ["Amazon Macie", "Amazon GuardDuty", "AWS Config", "Amazon Inspector"], "correct": 0, "explanation": "Macie uses machine learning to discover, classify, and protect sensitive data such as PII in S3. GuardDuty focuses on threat detection, AWS Config evaluates the compliance of resource configurations, and Inspector scans instances and containers for vulnerabilities."},
  {"id": 111, "domain": 1, "q": "A company manages TLS certificates for its websites served through CloudFront and an Application Load Balancer. It wants to automate certificate renewal at no additional cost. Which solution do you recommend?", "options": ["Purchase certificates from a third-party authority and import them manually each year", "Use AWS Certificate Manager (ACM) to provision public certificates with automatic renewal", "Store the certificates in Secrets Manager and renew them with a script", "Use CloudHSM to generate and sign the certificates"], "correct": 1, "explanation": "ACM provides public certificates for free that can be used with CloudFront and ALB, and renews them automatically, removing manual management. Importing third-party certificates (A) requires manual renewal, Secrets Manager (C) does not handle certificate issuance, and CloudHSM (D) is for storing cryptographic keys, not automating public certificates."},
  {"id": 112, "domain": 1, "q": "An application must encrypt data, but the company is subject to a regulation requiring dedicated, single-tenant hardware security modules (HSMs) that are FIPS 140-2 Level 3 compliant and over which it retains exclusive control. Which solution meets this requirement?", "options": ["AWS KMS with an AWS managed key", "AWS CloudHSM", "SSE-S3", "Secrets Manager"], "correct": 1, "explanation": "CloudHSM provides dedicated, single-tenant HSMs that are FIPS 140-2 Level 3 compliant and over which the customer retains exclusive control of the keys. KMS is a multi-tenant service (option A), SSE-S3 provides no control over the hardware, and Secrets Manager manages secrets, not dedicated HSMs."},
  {"id": 113, "domain": 1, "q": "A company is building a mobile application and wants to let users authenticate through their Google and Facebook accounts while obtaining temporary AWS credentials to access S3. Which service BEST handles user authentication and identity federation?", "options": ["IAM Identity Center (AWS SSO)", "Amazon Cognito (User Pools and Identity Pools)", "AWS Directory Service", "IAM roles with static access keys"], "correct": 1, "explanation": "Cognito handles authentication of web/mobile application users through User Pools and federation with social providers, and issues temporary AWS credentials through Identity Pools. IAM Identity Center targets workforce access to AWS accounts, Directory Service provides a managed directory, and static keys should be avoided for end users."},
  {"id": 114, "domain": 1, "q": "A company wants to ensure that none of its S3 buckets can be made publicly accessible by mistake, even if a permissive ACL or bucket policy is inadvertently applied. Which feature should it enable?", "options": ["S3 Object Lock in Governance mode", "S3 Block Public Access at the account level", "Bucket versioning", "Default SSE-KMS encryption"], "correct": 1, "explanation": "S3 Block Public Access, enabled at the account level, overrides any permissive ACL or bucket policy and prevents all public access, regardless of any later configuration. Object Lock (A) protects against object deletion, versioning (C) retains versions, and default encryption (D) protects data at rest without blocking public access."},
  {"id": 115, "domain": 1, "q": "A company wants to centralize and aggregate security findings from GuardDuty, Inspector, and Macie across multiple accounts, with compliance checks against standards such as CIS AWS Foundations. Which service provides this centralized view?", "options": ["AWS Security Hub", "Amazon CloudWatch", "AWS Config", "AWS Trusted Advisor"], "correct": 0, "explanation": "Security Hub aggregates and prioritizes findings from GuardDuty, Inspector, Macie, and other services, and runs automated compliance checks (CIS, AWS Foundational Security Best Practices). CloudWatch handles metrics/logs, Config tracks configuration changes, and Trusted Advisor provides general recommendations without this aggregation of security findings."},
  {"id": 116, "domain": 1, "q": "A company must give an external vendor temporary read-only access to certain resources in its AWS account. It wants to avoid any long-lived credentials and reduce the risk of the confused deputy problem. Which approach is the MOST secure?", "options": ["Create an IAM user for the vendor with a read-only policy", "Create an IAM role that can be assumed by the vendor's account, with a condition on an ExternalId", "Share the access keys of an existing role through an encrypted channel", "Add the vendor as a federated user through SAML without any condition"], "correct": 1, "explanation": "A cross-account role with an ExternalId protects against the confused deputy problem and provides temporary credentials without a long-lived secret. An IAM user (A) implies persistent credentials, sharing keys (C) is dangerous, and SAML federation without a condition (D) does not specifically address the confused deputy problem or the need for occasional third-party access."},
  {"id": 117, "domain": 1, "q": "A company requires that all data exchanged between its clients and its Application Load Balancer be encrypted in transit. Which configuration ensures encryption in transit?", "options": ["Configure an HTTPS listener on the ALB with an ACM certificate", "Enable SSE-KMS on the backend S3 bucket", "Configure a NACL allowing only port 443", "Enable EBS encryption on the target instances"], "correct": 0, "explanation": "An HTTPS listener on the ALB with an ACM certificate establishes a TLS connection that encrypts data in transit between the client and the load balancer. SSE-KMS (B) and EBS encryption (D) protect data at rest, and a NACL (C) filters traffic without ensuring encryption of the content."},
  {"id": 118, "domain": 1, "q": "A company wants to scan its EC2 instances and ECR container images for software vulnerabilities (CVEs) and unintended network exposure, in an automated and continuous manner. Which service is the MOST suitable?", "options": ["Amazon Inspector", "Amazon Macie", "AWS WAF", "Amazon GuardDuty"], "correct": 0, "explanation": "Amazon Inspector continuously assesses EC2 instances, Lambda functions, and ECR images to detect software vulnerabilities (CVEs) and network exposure. Macie targets sensitive data, WAF filters web traffic, and GuardDuty detects behavioral threats but does not perform software vulnerability scanning."},
  {"id": 119, "domain": 1, "q": "A company has a VPC with public and private subnets. The instances in the private subnets must download software updates from the internet but must not be reachable from the internet. Which solution meets this need?", "options": ["Attach an Internet Gateway and assign a public IP to the private instances", "Deploy a NAT Gateway in a public subnet and route the outbound traffic from the private subnets to it", "Configure a Gateway VPC endpoint for all internet traffic", "Use a NACL that allows all inbound traffic on the private subnets"], "correct": 1, "explanation": "A NAT Gateway in a public subnet allows private instances to initiate outbound connections to the internet while preventing unsolicited inbound connections. Assigning a public IP (A) would expose the instances, a Gateway endpoint (C) only covers S3/DynamoDB, and opening the NACL inbound (D) would increase exposure."},
  {"id": 120, "domain": 1, "q": "A SaaS company wants to expose its service to customers hosted in their own VPCs, privately and without going over the internet, without having to manage peering or expose IP address ranges. Which AWS technology BEST meets this need?", "options": ["VPC Peering between each customer and the provider", "AWS PrivateLink with an endpoint service (Interface endpoints on the customer side)", "A shared Internet Gateway", "A dedicated AWS Direct Connect for each customer"], "correct": 1, "explanation": "PrivateLink lets you expose a service through an endpoint service, with customers accessing it through private Interface endpoints in their VPC, without peering or IP address exposure. VPC Peering (A) requires non-overlapping CIDR management and a complex mesh, the Internet Gateway (C) involves the internet, and Direct Connect (D) concerns on-premises connectivity."},
  {"id": 121, "domain": 1, "q": "A financial company must ensure that certain log files stored in S3 cannot be deleted or modified during a regulatory period of 7 years, even by administrators with full privileges. Which S3 feature meets this WORM requirement?", "options": ["S3 Versioning alone", "S3 Object Lock in Compliance mode with a retention period", "Block Public Access enabled", "A Lifecycle policy moving objects to Glacier"], "correct": 1, "explanation": "S3 Object Lock in Compliance mode enforces a strict WORM model: no user, including the root account, can delete or modify the object before the end of the retention period. Versioning alone (A) does not prevent deletion, Block Public Access (C) manages public access, and a lifecycle policy (D) does not provide immutability."},
  {"id": 122, "domain": 1, "q": "A large company centralizes its employees' access management across multiple AWS accounts and applications. It already has an external identity provider (Okta) and wants to assign permissions by group without creating IAM users in each account. Which service is the MOST appropriate?", "options": ["Amazon Cognito", "AWS IAM Identity Center (successor to AWS SSO) integrated with Okta", "IAM users replicated in each account", "AWS Directory Service Simple AD"], "correct": 1, "explanation": "IAM Identity Center integrates with external identity providers such as Okta and lets you assign permission sets to groups for SSO access to multiple accounts, without IAM users per account. Cognito (A) targets client application users, replicating IAM users (C) is unmanageable, and Simple AD (D) is a directory without this federated multi-account SSO capability."},
  {"id": 123, "domain": 1, "q": "A company wants to harden the security of the root user of its management AWS account. Which measure is the MOST important best practice to apply first?", "options": ["Create access keys for the root user to automate tasks", "Enable MFA on the root user and use it only for tasks that require root", "Share the root credentials with the on-call team", "Attach an AdministratorAccess policy to the root user"], "correct": 1, "explanation": "Enabling MFA on the root user and limiting its use to tasks that truly require it is a fundamental AWS security best practice. Creating root access keys (A) is strongly discouraged, sharing credentials (C) creates a major risk, and attaching a policy to root (D) is pointless because root already has unrestricted access."},
  {"id": 124, "domain": 1, "q": "A company stores objects in S3 and wants each user to provide and manage their own encryption key, without AWS storing it, while still using server-side encryption. Which S3 encryption option fits?", "options": ["SSE-S3", "SSE-KMS", "SSE-C (customer-provided keys)", "EBS encryption"], "correct": 2, "explanation": "SSE-C lets the client provide its own encryption key with each request; S3 encrypts/decrypts on the server side but never stores the key. SSE-S3 (A) and SSE-KMS (B) manage keys through AWS, and EBS encryption (D) does not apply to S3 objects."},
  {"id": 125, "domain": 1, "q": "A company finds that a NACL associated with a subnet blocks the return traffic of certain outbound connections, while a Security Group works correctly in a similar situation. Which statement correctly explains this behavior?", "options": ["NACLs are stateful, Security Groups are stateless", "NACLs are stateless and require explicit rules for return traffic (ephemeral ports), whereas Security Groups are stateful", "Security Groups evaluate rules in numerical order, NACLs do not", "NACLs apply only to inbound traffic"], "correct": 1, "explanation": "NACLs are stateless: return traffic must be explicitly allowed, typically on ephemeral ports, whereas Security Groups are stateful and automatically allow the responses. Option A reverses the concepts, NACLs (not SGs) are evaluated by rule number (C is false), and NACLs apply in both directions (D is false)."},
  {"id": 126, "domain": 1, "q": "A company is being targeted by sophisticated layer 3, 4, and 7 DDoS attacks on its applications exposed through CloudFront, ALB, and Route 53. It wants advanced protection with access to a DDoS Response Team (DRT) and protection against cost spikes. Which service should it subscribe to?", "options": ["AWS Shield Standard", "AWS Shield Advanced", "AWS WAF only", "Amazon GuardDuty"], "correct": 1, "explanation": "Shield Advanced offers enhanced DDoS protection, access to the DDoS Response Team, detailed reports, and financial protection against attack-related costs. Shield Standard (A) offers basic protection without the DRT, WAF alone (C) filters layer 7 without these guarantees, and GuardDuty (D) does not perform DDoS mitigation."},
  {"id": 127, "domain": 1, "q": "A company wants to select the appropriate mechanisms to encrypt data AT REST on AWS. Which of the following options provide encryption of data at rest? (Choose THREE answers.)", "multi": true, "options": ["SSE-KMS on an S3 bucket", "EBS volume encryption", "An HTTPS listener on an ALB", "Encryption enabled on an RDS cluster", "An IPsec site-to-site VPN"], "correct": [0, 1, 3], "explanation": "SSE-KMS on S3, EBS volume encryption, and RDS encryption all protect data at rest. The HTTPS listener on the ALB (C) and the IPsec VPN (E) provide encryption in transit, not at rest."},
  {"id": 128, "domain": 1, "q": "A company is designing an authorization strategy and wants to apply several IAM security best practices. Which statements reflect best practices recommended by AWS? (Choose TWO answers.)", "multi": true, "options": ["Grant the broadest possible permissions to avoid blockers, then restrict later", "Apply the principle of least privilege by granting only the necessary permissions", "Use IAM roles rather than long-lived access keys for applications on EC2", "Store root access keys in a shared secret for the team", "Disable CloudTrail to reduce logging costs"], "correct": [1, 2], "explanation": "Least privilege and the use of IAM roles (rather than static keys) are key AWS recommendations. Granting broad permissions (A) violates least privilege, sharing root keys (D) is dangerous, and disabling CloudTrail (E) removes security traceability."},
  {"id": 129, "domain": 1, "q": "A company wants to encrypt traffic and finely inspect/filter network traffic (domain filtering, intrusion prevention) between its VPCs and to the internet, in a managed way and at scale. Which AWS service is designed for this advanced stateful network filtering?", "options": ["AWS Network Firewall", "Security Groups", "AWS WAF", "Amazon GuardDuty"], "correct": 0, "explanation": "AWS Network Firewall is a managed, stateful network firewall that enables domain filtering, IPS/IDS, and fine-grained traffic rules at the VPC level. Security Groups (B) operate at the instance level without advanced inspection, WAF (C) filters the HTTP application layer, and GuardDuty (D) detects threats without filtering traffic."},
  {"id": 130, "domain": 1, "q": "A company wants to choose between AWS Secrets Manager and SSM Parameter Store to store configuration parameters and secrets. Which statements are correct to guide this choice? (Choose TWO answers.)", "multi": true, "options": ["Secrets Manager supports native automatic rotation of secrets, unlike standard Parameter Store", "Parameter Store offers a free standard tier for storing configuration parameters", "Parameter Store offers built-in automatic rotation for RDS databases", "Secrets Manager cannot encrypt values with KMS", "Neither service can be used to store connection strings"], "correct": [0, 1], "explanation": "Secrets Manager provides native automatic rotation (useful for database credentials) while Parameter Store offers a free standard tier for configuration parameters. Option C wrongly attributes native rotation to Parameter Store, D is false because Secrets Manager encrypts through KMS, and E is false because both can store connection strings."},

  {"id": 201, "domain": 2, "q": "A business-critical web application runs on EC2 instances behind an Application Load Balancer in a single Availability Zone. The company wants to eliminate this single point of failure with minimal effort. What do you recommend?", "options": ["Enable S3 versioning to back up application data", "Deploy the EC2 instances across at least two Availability Zones using a multi-AZ Auto Scaling group and register those AZs with the ALB", "Migrate the application to a single larger instance (scale-up) in the same AZ", "Create a second Region and replicate the application there in Active-Active"], "correct": 1, "explanation": "Spreading the Auto Scaling group across multiple AZs and enabling those AZs on the ALB eliminates the single-AZ SPOF while remaining simple and inexpensive. S3 versioning protects objects but not compute availability. Scaling up in the same AZ does not remove the SPOF. Multi-Region Active-Active meets the need but is significantly more complex and costly than necessary."},
  {"id": 202, "domain": 2, "q": "A production RDS MySQL database must remain available even if an Availability Zone fails, with automatic failover. Which configuration meets this need?", "options": ["Enable multiple Read Replicas in the same AZ", "Enable RDS Multi-AZ deployment", "Enable automated backups with a 35-day retention", "Create a cross-Region Read Replica"], "correct": 1, "explanation": "RDS Multi-AZ maintains a synchronous standby replica in another AZ and fails over automatically through DNS in the event of a failure. Read Replicas are used to scale reads, not for automatic failover of the primary database. Automated backups enable restoration but not instant high availability. A cross-Region Read Replica addresses geographic DR, not automatic AZ failover."},
  {"id": 203, "domain": 2, "q": "A team is decoupling an order processing service. The exact processing order of messages must be guaranteed and each order must be processed exactly once. Which service should be used?", "options": ["SQS Standard queue", "SNS Standard topic", "SQS FIFO queue", "Kinesis Data Firehose"], "correct": 2, "explanation": "An SQS FIFO queue guarantees strict ordering (First-In-First-Out) and exactly-once processing, which is exactly what is required. SQS Standard offers unlimited throughput but only best-effort ordering and at-least-once delivery. SNS is a pub/sub service for fan-out, not an ordered queue. Kinesis Firehose is for ingestion into storage destinations, not ordered transactional decoupling."},
  {"id": 204, "domain": 2, "q": "A company must design a Disaster Recovery strategy with an RTO of a few minutes and an RPO close to zero, while keeping costs under control by running a scaled-down version of the environment in the secondary Region at all times. Which strategy fits?", "options": ["Backup & Restore", "Pilot Light", "Warm Standby", "Multi-site Active-Active"], "correct": 2, "explanation": "Warm Standby keeps a scaled-down but functional version of the environment running at all times in the secondary Region, enabling rapid scaling for an RTO of a few minutes and a low RPO. Backup & Restore has much higher RTO/RPO (hours). Pilot Light runs only the core (often the replicated database) without active application servers, giving a longer RTO. Active-Active offers a near-zero RTO but at a much higher cost and is not a 'scaled-down' version."},
  {"id": 205, "domain": 2, "q": "An Application Load Balancer distributes traffic to an Auto Scaling group. Users complain that their sessions are lost when traffic is redirected to another instance. Without modifying the application, which solution maintains session affinity?", "options": ["Enable cross-zone load balancing on the ALB", "Enable sticky sessions (session affinity) based on a duration cookie on the target group", "Switch to a Network Load Balancer", "Increase the ALB health check interval"], "correct": 1, "explanation": "ALB sticky sessions use a cookie to route requests from the same client to the same instance, preserving session state without changing the application. Cross-zone load balancing balances traffic across AZs but does not handle affinity. An NLB can provide source-IP affinity but is a heavier change and less suited to HTTP. Changing the health check has no bearing on session persistence."},
  {"id": 206, "domain": 2, "q": "An image processing application sends jobs into an SQS queue. Some messages consistently fail and block processing in a loop. How can you isolate these problematic messages for analysis without disrupting the main queue?", "options": ["Increase the visibility timeout of the main queue", "Configure a Dead-Letter Queue (DLQ) with a maxReceiveCount", "Enable long polling on the main queue", "Enable SSE encryption on the main queue"], "correct": 1, "explanation": "A Dead-Letter Queue associated with a maxReceiveCount automatically redirects messages that repeatedly fail to a separate queue, isolating 'poison messages' for analysis. Increasing the visibility timeout only delays retries. Long polling reduces empty calls but does not handle failures. SSE encryption concerns security, not failure handling."},
  {"id": 207, "domain": 2, "q": "A company wants to serve a global application with a relational database offering low-latency reads in multiple Regions and regional failover in the event of a disaster (RPO typically under a second, RTO of about a minute). Which solution should it choose?", "options": ["Amazon Aurora Global Database", "RDS Multi-AZ with a Read Replica in the same Region", "DynamoDB with DAX", "Aurora Serverless v2 in a single Region"], "correct": 0, "explanation": "Aurora Global Database replicates data to up to five secondary Regions with replication latency typically under a second, offering local reads and rapid regional promotion (RTO ~1 min). RDS Multi-AZ + Read Replica remains single-Region. DynamoDB+DAX is NoSQL, not relational. Aurora Serverless v2 single-Region does not provide the required multi-Region resilience."},
  {"id": 208, "domain": 2, "q": "You must route traffic to a primary Region and automatically fail over to a secondary Region only if the primary becomes unavailable. Which Route 53 combination should you use?", "options": ["Weighted routing policy with weights 100/0", "Failover routing policy with health checks associated with the records", "Geolocation routing policy", "Multivalue answer routing policy"], "correct": 1, "explanation": "Route 53 Failover policy, combined with health checks, directs traffic to the primary record as long as it is healthy and fails over to the secondary if the health check fails. Weighted 100/0 does not fail over automatically on failure. Geolocation routes based on the geographic location of users. Multivalue answer returns multiple healthy IPs but does not implement an active/passive primary/secondary scheme."},
  {"id": 209, "domain": 2, "q": "An architecture uses SNS to notify several downstream systems. One of the subscribers (a Lambda function) sometimes fails and notifications are lost. Which approach(es) improve delivery reliability? (Choose TWO answers.)", "multi": true, "options": ["Configure a Dead-Letter Queue (redrive policy) on the SNS subscription", "Insert an SQS queue between SNS and the consumer (SNS-SQS fan-out)", "Enable cross-zone load balancing", "Convert the SNS topic to SQS FIFO", "Reduce the DNS TTL of the endpoint"], "correct": [0, 1], "explanation": "A DLQ on the SNS subscription captures messages that are undelivered after retries, and the SNS to SQS fan-out pattern buffers messages in a durable queue that the consumer processes at its own pace: both improve reliability. Cross-zone load balancing and DNS TTL do not relate to message delivery. SNS does not 'convert' into SQS FIFO; they are distinct services."},
  {"id": 210, "domain": 2, "q": "An application on EC2 must store shared files accessed simultaneously by dozens of Linux instances spread across multiple Availability Zones, with high availability of the storage. Which service is the MOST suitable?", "options": ["Amazon EBS multi-attach in a single AZ", "Amazon EFS (Elastic File System)", "Local instance store", "Amazon FSx for Windows File Server"], "correct": 1, "explanation": "Amazon EFS is a managed NFS file system, accessible simultaneously by many Linux instances across multiple AZs, with built-in redundancy. EBS multi-attach is limited to a single AZ and a small number of instances. Instance store is ephemeral and local to the instance. FSx for Windows targets the SMB/Windows protocol, not Linux."},
  {"id": 211, "domain": 2, "q": "A company stores critical objects in an S3 bucket and wants to protect against accidental deletions and overwrites, while being able to restore a previous version of an object. What should it enable?", "options": ["S3 Transfer Acceleration", "S3 Versioning", "S3 Intelligent-Tiering", "S3 Requester Pays"], "correct": 1, "explanation": "S3 Versioning keeps all versions of an object, allowing recovery of a previous version after an overwrite and neutralizing an accidental deletion (delete marker). Transfer Acceleration optimizes transfer speed. Intelligent-Tiering optimizes storage costs based on access. Requester Pays shifts charges to the requester; none of these three protect against deletions."},
  {"id": 212, "domain": 2, "q": "For compliance reasons, a company must keep a copy of all its S3 objects in a Region located in another country, automatically and continuously. Which feature should it use?", "options": ["S3 Same-Region Replication (SRR)", "S3 Cross-Region Replication (CRR)", "S3 Lifecycle policy to Glacier", "EBS snapshots copied cross-Region"], "correct": 1, "explanation": "S3 Cross-Region Replication (CRR) automatically and continuously replicates objects to a bucket located in another Region, meeting the geographic compliance requirement. SRR replicates within the same Region, which does not satisfy the need for another country. A lifecycle policy to Glacier changes the storage class but does not move data to another Region. EBS snapshots concern block volumes, not S3 objects."},
  {"id": 213, "domain": 2, "q": "An Auto Scaling group must add or remove instances to maintain average CPU utilization around 50%, automatically adjusting to load without manually defining high/low thresholds. Which scaling policy should it choose?", "options": ["Simple scaling policy", "Target tracking scaling policy", "Scheduled scaling", "Manual scaling"], "correct": 1, "explanation": "Target tracking automatically adjusts capacity to maintain a target metric (here 50% average CPU), managing the thresholds itself, which matches the need exactly. Simple scaling requires manually defined thresholds and cooldowns. Scheduled scaling is based on known schedules, not real-time load. Manual scaling requires human intervention."},
  {"id": 214, "domain": 2, "q": "An application receives requests through an API. Duplicate network calls can occur during retries, and you want to prevent the same operation (e.g., charging a payment) from being executed twice. Which design principle should you apply?", "options": ["Increase the number of instances in the Auto Scaling group", "Design the operation to be idempotent (e.g., using a unique request identifier / idempotency key)", "Enable sticky sessions on the ALB", "Use an NLB rather than an ALB"], "correct": 1, "explanation": "Idempotency, for example through a unique idempotency key per request, ensures that a repeated operation produces the same result without double execution, which exactly solves the retry problem. Adding instances does nothing about duplicates. Sticky sessions handle session affinity, not operation uniqueness. The choice between ALB and NLB does not prevent double processing."},
  {"id": 215, "domain": 2, "q": "A company orchestrates a data processing workflow with multiple steps, automatic retries, per-step error handling, and conditional paths, without coding this logic into the application. Which AWS service is the MOST suitable?", "options": ["AWS Step Functions", "Amazon SQS Standard", "AWS Batch alone", "Amazon SNS"], "correct": 0, "explanation": "AWS Step Functions orchestrates workflows as steps (state machine) with built-in retries, error catching, and conditional branching, without orchestration logic in the code. SQS decouples but does not orchestrate a multi-step workflow. AWS Batch runs batch jobs but does not provide rich conditional orchestration. SNS only does pub/sub notification."},
  {"id": 216, "domain": 2, "q": "You must load-balance very high-throughput, low-latency TCP traffic, with millions of requests per second and preservation of the client's source IP address. Which load balancer should you choose?", "options": ["Application Load Balancer (ALB)", "Network Load Balancer (NLB)", "Gateway Load Balancer (GLB)", "Classic Load Balancer (CLB)"], "correct": 1, "explanation": "The Network Load Balancer operates at layer 4, handles millions of requests/s at very low latency, and preserves the client source IP. The ALB operates at layer 7 (HTTP/HTTPS) and is not suitable for high-performance raw TCP. The GLB is used to insert virtual security appliances. The CLB is an older, less performant generation and is discouraged for new deployments."},
  {"id": 217, "domain": 2, "q": "A company wants to centralize and automate backups of several services (EBS, RDS, DynamoDB, EFS) with retention policies and cross-Region copies of the backups, all from a single place. Which service should it use?", "options": ["Create cron scripts on EC2 for each service", "AWS Backup with backup plans and cross-Region copy", "Enable only the automated backups of each service separately", "S3 Lifecycle policies"], "correct": 1, "explanation": "AWS Backup centralizes backup management for multiple services through backup plans, with built-in retention and cross-Region copy from a single console. Homemade cron scripts are fragile and not centralized. Per-service automated backups are neither centralized nor unified. S3 lifecycle policies only manage S3 objects."},
  {"id": 218, "domain": 2, "q": "An RDS database experiences a heavy read load that degrades performance, while writes remain moderate. The goal is to improve read scalability without impacting the primary database. Which solution is appropriate?", "options": ["Enable Multi-AZ for the primary database", "Create one or more Read Replicas and route read traffic to them", "Increase the retention of automated backups", "Convert the database to magnetic storage"], "correct": 1, "explanation": "Read Replicas asynchronously replicate the primary database and absorb read traffic, improving scalability without overloading the primary. Multi-AZ is for failover/HA, not read scaling (the standby does not accept reads in classic RDS). Increasing backup retention does not improve performance. Switching to magnetic storage would instead degrade performance."},
  {"id": 219, "domain": 2, "q": "A DR strategy must minimize costs by storing only backups in the secondary Region, with no active infrastructure, accepting an RTO of several hours. How is this approach characterized and what is its main trade-off?", "options": ["Backup & Restore; the highest RTO/RPO but the lowest cost", "Warm Standby; low RTO but high cost", "Pilot Light; full infrastructure always active", "Active-Active; zero RTO and the lowest cost"], "correct": 0, "explanation": "Backup & Restore simply stores backups and rebuilds the environment at the time of disaster: it is the least expensive option but with the highest RTO/RPO (hours). Warm Standby involves a reduced active infrastructure. Pilot Light does not keep a full active infrastructure. Active-Active is not low cost and offers a near-zero RTO, which contradicts the statement."},
  {"id": 220, "domain": 2, "q": "For an event-driven system, a company wants to route events from various sources (AWS services, SaaS applications, in-house applications) to multiple targets based on content filtering rules, without managing infrastructure. Which service is the MOST suitable?", "options": ["Amazon EventBridge", "Amazon SQS FIFO", "AWS Direct Connect", "Amazon MQ"], "correct": 0, "explanation": "Amazon EventBridge is a serverless event bus that ingests events from AWS sources, SaaS partners, and custom applications, then routes them to targets based on pattern matching rules. SQS FIFO is a message queue, without content-based routing. Direct Connect is a dedicated network connection. Amazon MQ is a managed message broker for legacy protocols, without EventBridge's rule-based routing."},
  {"id": 221, "domain": 2, "q": "An HPC workload on Windows requires a high-performance shared file system that is SMB-compatible, durable, and highly available across multiple AZs. Which solution should you recommend?", "options": ["Amazon EFS", "Amazon FSx for Windows File Server in a Multi-AZ configuration", "Amazon S3 mounted through the CLI", "EBS gp3 shared between instances"], "correct": 1, "explanation": "FSx for Windows File Server provides a native Windows, high-performance SMB share, and its Multi-AZ configuration ensures availability with a standby in another AZ. EFS is an NFS service for Linux, not SMB/Windows. S3 is not a natively mounted file system and is not suited to the SMB protocol. EBS gp3 is not a network file share suited to this need."},
  {"id": 222, "domain": 2, "q": "An Auto Scaling group launches instances, but they take about 8 minutes to bootstrap and pass the application health checks. The ASG is observed to prematurely replace instances deemed 'unhealthy' during their startup. Which parameter should be adjusted?", "options": ["The cooldown period to 0 seconds", "The health check grace period to cover the startup time", "The desired capacity to its maximum value", "The health check type from EC2 to ELB only"], "correct": 1, "explanation": "The health check grace period defines the delay before the ASG begins evaluating the health of a freshly launched instance; increasing it (beyond the 8 minutes) avoids premature replacements. Setting the cooldown to 0 has no effect on this startup window. Forcing the desired capacity to its maximum wastes resources without solving the problem. Changing the health check type does not fix the bootstrap delay."},
  {"id": 223, "domain": 2, "q": "A company is designing a multi-Region Active-Active architecture for a global web application in order to offer minimal latency to users and regional fault tolerance. Which statement(s) are correct about this approach? (Choose TWO answers.)", "multi": true, "options": ["Route 53 latency-based routing can direct each user to the nearest Region", "It is the least expensive DR option of all", "A global database (e.g., DynamoDB Global Tables or Aurora Global Database) is necessary for data consistency across Regions", "The RTO is generally several hours", "Active-Active mandatorily requires a single AZ per Region"], "correct": [0, 2], "explanation": "Route 53 latency-based routing sends each user to the Region offering the lowest latency, and a global database (DynamoDB Global Tables, Aurora Global Database) is essential to synchronize data across active Regions. Active-Active is the most expensive option, not the cheapest, and its RTO is near zero (not several hours). Nothing mandates a single AZ per Region; on the contrary, you deploy multi-AZ for local resilience."},
  {"id": 224, "domain": 2, "q": "A team wants to design a DR setup where the core of the system (notably the continuously replicated database) remains active in the secondary Region, but where the application servers are only started and scaled at the time of disaster. Which strategy describes this?", "options": ["Backup & Restore", "Pilot Light", "Warm Standby", "Multi-site Active-Active"], "correct": 1, "explanation": "Pilot Light continuously maintains the critical core (replicated database, minimal configuration) while the application servers are off and only provisioned/started during failover. Backup & Restore has no active infrastructure. Warm Standby runs a scaled-down but already functional version of the entire application stack. Active-Active runs the whole stack in production simultaneously in both Regions."},
  {"id": 225, "domain": 2, "q": "An application places video processing requests into an SQS queue consumed by an Auto Scaling group of workers. To make the architecture resilient to spikes, how can you automatically size the workers based on the actual queue load?", "options": ["Scale the ASG based on the CloudWatch ApproximateNumberOfMessagesVisible metric (or backlog per instance)", "Scale the ASG only based on the ALB's network utilization", "Manually set the desired capacity to twice the observed maximum", "Use scheduled scaling based on the time of day"], "correct": 0, "explanation": "Scaling the ASG on the SQS ApproximateNumberOfMessagesVisible metric (ideally a target backlog per instance) aligns the number of workers with the actual queue depth, efficiently handling spikes. The ALB network metric is not relevant here because the workers consume a queue, not an ALB. Manually setting a high capacity wastes resources and does not adapt. Scheduled scaling ignores unpredictable queue spikes."},

  {"id":301,"domain":3,"q":"A mobile gaming application uses a DynamoDB table to store leaderboards. During peak hours, millions of players view the same leaderboards, generating intense read traffic on a few very popular items (hot keys), which causes throttling and high latency. The solution must provide microsecond-level reads without modifying the application logic. What do you recommend?","options":["Enable DynamoDB Accelerator (DAX) in front of the table","Add Read Replicas to the DynamoDB table","Enable ElastiCache for Memcached and manually replicate the leaderboards into it","Increase the provisioned read capacity (RCU) to the maximum"],"correct":0,"explanation":"DAX is a fully managed in-memory cache natively integrated with DynamoDB, providing microsecond-level reads and absorbing hot keys without changing the code (same API). DynamoDB does not have Read Replicas. Memcached is not natively integrated and requires manual management. Increasing RCUs is costly and does not solve microsecond latency or the hot-key problem on a single partition."},
  {"id":302,"domain":3,"q":"A company serves static video content and images from an S3 bucket to a global audience. Users in Asia and South America complain about slow loading times. Which solution BEST improves delivery performance with minimal operational overhead?","options":["Enable S3 Transfer Acceleration on the bucket","Distribute the content through a CloudFront distribution with the S3 bucket as origin","Replicate the S3 bucket to all regions and route with Route 53 latency-based routing","Place an Application Load Balancer in front of the S3 bucket"],"correct":1,"explanation":"CloudFront caches static content at edge locations close to users worldwide, greatly reducing delivery latency. S3 Transfer Acceleration optimizes uploads to S3, not delivery to readers. Multi-region replication is costly and complex. An ALB cannot serve an S3 bucket directly and provides no edge caching."},
  {"id":303,"domain":3,"q":"A MySQL database on Amazon RDS is experiencing saturation: the application is read-intensive (reports, analytical dashboards) while writes remain moderate. The reporting queries are slowing down transactions. How can you improve read performance without impacting writes?","options":["Enable Multi-AZ deployment to distribute the read load","Create one or more Read Replicas and route the reporting queries to them","Change the instance class to a larger type only","Enable encryption at rest to speed up reads"],"correct":1,"explanation":"RDS Read Replicas offload read traffic to asynchronously replicated copies, ideal for reporting without penalizing writes on the primary. Multi-AZ provides high availability (the standby is not readable), not read scaling. Enlarging the instance helps but does not separate reads/writes. Encryption has no effect on read performance."},
  {"id":304,"domain":3,"q":"A high-frequency trading platform deploys an EC2 compute cluster that requires extremely low network latency and high throughput between nodes located in the same Availability Zone. Which configuration offers the best inter-instance network performance?","options":["A spread placement group across multiple AZs","A cluster placement group with instances supporting Enhanced Networking (ENA)","A partition placement group spread across three AZs","Spreading the instances behind a Network Load Balancer"],"correct":1,"explanation":"The cluster placement group groups instances on the same rack within an AZ to minimize latency and maximize throughput, and Enhanced Networking (ENA/EFA) reinforces this gain. The spread placement group isolates instances (anti-affinity) for resilience, increasing latency. Partition placement groups target distributed workloads (HDFS/Kafka). An NLB adds a network hop."},
  {"id":305,"domain":3,"q":"A web application runs on an Auto Scaling Group behind an ALB. The traffic shows predictable spikes every business day at 9 AM and a drop at 6 PM, but also unexpected spikes. The team wants the capacity to be ready BEFORE the predictable spikes while reacting to unexpected spikes. Which combination should they choose? (Choose TWO answers.)","multi":true,"options":["Scheduled scaling to increase capacity just before 9 AM","Target tracking scaling on CPU utilization for the unexpected spikes","Manual scaling triggered by the operator every morning","A single Spot Fleet with no scaling policy","Disable health checks to speed up startup"],"correct":[0,1],"explanation":"Scheduled scaling provisions capacity at known times (before 9 AM), guaranteeing availability before predictable spikes. Target tracking dynamically adjusts based on a metric (CPU) to absorb unexpected spikes. Manual scaling is neither reliable nor automatic. A Spot Fleet with no policy does not scale, and disabling health checks degrades reliability without helping performance."},
  {"id":306,"domain":3,"q":"A data team must run ad hoc SQL queries directly on log files in Parquet format stored in S3, without provisioning or managing infrastructure, and pay only per query. Which service is the MOST suitable?","options":["Amazon Redshift with COPY loading from S3","Amazon Athena","Amazon RDS for PostgreSQL with file import","Amazon EMR with a permanent Hive cluster"],"correct":1,"explanation":"Athena is a serverless service that queries data directly in S3 using SQL, without infrastructure, billed by the amount of data scanned (the Parquet format reduces this cost). Redshift requires a cluster and prior loading. RDS is not designed to query S3 files ad hoc. A permanent EMR cluster involves ongoing management and cost, the opposite of the serverless need."},
  {"id":307,"domain":3,"q":"A file-sharing application requires a shared file system mounted simultaneously by hundreds of Linux EC2 instances, with throughput that must grow automatically based on the data size and support thousands of parallel operations. Which storage solution should you choose?","options":["An io2 EBS volume multi-attached to all instances","Amazon EFS in General Purpose performance mode and Elastic throughput","An st1 EBS volume shared through a self-managed NFS server","Local instance store replicated between instances"],"correct":1,"explanation":"EFS is a managed NFS file system, mountable by thousands of instances in parallel, that scales automatically and offers Elastic throughput mode adapting to the load. EBS Multi-Attach (io2) is limited to a small number of instances within an AZ and is not a global NFS share. A self-managed NFS on st1 adds management and a bottleneck. Instance store is ephemeral and local."},
  {"id":308,"domain":3,"q":"A company is migrating a workload requiring high IOPS and independently configurable throughput, at optimized cost, for a medium-sized transactional database (500 GB). It wants to avoid oversizing the volume just to obtain IOPS. Which EBS volume type should you recommend?","options":["gp2, increasing the volume size to obtain more IOPS","gp3, provisioning IOPS and throughput independently of size","st1, optimized for sequential throughput","sc1, for infrequently accessed data"],"correct":1,"explanation":"gp3 lets you provision IOPS (up to 16,000) and throughput (up to 1,000 MB/s) independently of capacity, at a lower cost than gp2, avoiding oversizing. gp2 ties IOPS to the volume size, forcing oversizing. st1 and sc1 are HDD volumes oriented toward sequential throughput and cold data, unsuitable for a transactional database requiring high IOPS."},
  {"id":309,"domain":3,"q":"A media company continuously ingests clickstreams at very high throughput (several GB/s) and must process them in real time with multiple independent consumers, with replay of the data possible for 7 days. Which ingestion service should it choose?","options":["Amazon SQS Standard","Amazon Kinesis Data Streams","Amazon SNS","Amazon Kinesis Data Firehose"],"correct":1,"explanation":"Kinesis Data Streams handles massive throughput through sharding, allows multiple simultaneous consumers (fan-out), and retains data for up to 7 days (or even 365) for replay. SQS does not allow replay or multi-consumer reading of the same message in this way. SNS is pub/sub without retention for replay. Firehose delivers to destinations (S3, Redshift) without true real-time, multi-consumer processing with replay."},
  {"id":310,"domain":3,"q":"A serverless API based on Lambda behind API Gateway experiences sudden traffic spikes. During these spikes, users suffer latency due to cold starts, and some invocations are throttled. The application is critical and latency must stay low from the very first request. Which measures should you apply? (Choose TWO answers.)","multi":true,"options":["Configure Provisioned Concurrency on the Lambda function","Request an increase of the account's concurrency quota","Migrate the logic to EC2 with a large placement group","Enable FIFO mode on API Gateway","Reduce the memory allocated to the function to the minimum"],"correct":[0,1],"explanation":"Provisioned Concurrency keeps pre-initialized execution environments, eliminating cold starts for consistent latency. Increasing the account's concurrency quota avoids throttling during spikes. Migrating to EC2 contradicts the serverless approach. API Gateway has no relevant FIFO mode here. Reducing memory also lowers the allocated CPU and increases latency."},
  {"id":311,"domain":3,"q":"A global application running on EC2 instances in multiple regions needs a single network entry point, fast regional failover, and a performance improvement for non-HTTP TCP/UDP traffic (online gaming, IoT). The content is not cacheable. Which solution is the MOST suitable?","options":["Amazon CloudFront with multiple origins","AWS Global Accelerator with endpoints in each region","Route 53 with geolocation routing only","A global Application Load Balancer"],"correct":1,"explanation":"Global Accelerator provides static anycast IPs, routes traffic through the AWS backbone network to reduce latency, supports TCP/UDP, and fails over quickly between regions, ideal for non-HTTP, non-cacheable traffic. CloudFront is optimized for cacheable HTTP content. Geolocation Route 53 does DNS without network acceleration or a fixed entry IP. The ALB is not global and does not cover UDP."},
  {"id":312,"domain":3,"q":"A web session application stores user sessions and requires an in-memory cache with persistence, read replicas, automatic failover (Multi-AZ), and advanced data structures (lists, sorted sets). Which ElastiCache engine should you choose?","options":["ElastiCache for Memcached, for its multi-threaded architecture","ElastiCache for Redis, for replication and rich data structures","DynamoDB with TTL enabled","An io2 EBS volume mounted as a RAM disk"],"correct":1,"explanation":"ElastiCache for Redis supports replication, Multi-AZ with automatic failover, persistence, and advanced data structures (lists, sorted sets), perfect for resilient sessions. Memcached is multi-threaded but without persistence, replication, or rich structures. DynamoDB is not a microsecond in-memory cache. A RAM disk on EBS is neither managed nor resilient."},
  {"id":313,"domain":3,"q":"A video processing application must write and read large temporary files with maximum disk throughput and the lowest possible latency, and it tolerates losing this data if the instance stops. Which storage offers the best performance for these ephemeral files?","options":["A gp3 EBS volume","Instance store (NVMe) attached to the instance","Amazon EFS","An sc1 EBS volume"],"correct":1,"explanation":"NVMe instance store is physically attached to the host, offering the highest throughput and the lowest latency, ideal for temporary data whose loss is acceptable on stop/terminate. EBS gp3 is performant but remains network storage, slower than local. EFS is shared and oriented toward aggregate throughput, not minimal local latency. sc1 is cold HDD, the slowest."},
  {"id":314,"domain":3,"q":"An e-commerce application on DynamoDB sees its partitions become hot partitions because the chosen partition key (for example the current date) concentrates all writes on a single partition during sales events. How can you improve the distribution and write performance?","options":["Increase only the provisioned write throughput (WCU)","Design a high-cardinality partition key or add a write-sharding suffix","Enable DAX in front of the table","Convert the table to fixed provisioned capacity mode"],"correct":1,"explanation":"A high-cardinality partition key (or adding a random/computed suffix to spread writes, write sharding) evenly distributes the load across partitions and removes the hot partition. Increasing WCUs does not fix the concentration on a single partition. DAX is a read cache, with no effect on writes. Fixed provisioned mode does not improve key distribution."},
  {"id":315,"domain":3,"q":"A company loads log data from Kinesis Data Streams to S3 and then to Redshift for analytics, but wants to minimize infrastructure management and buffer/transform the data before delivery, without writing consumer code. Which service should it use for delivery?","options":["Amazon Kinesis Data Firehose","A Kinesis Client Library (KCL) application on EC2","Amazon SQS with custom polling","AWS Glue with scheduled Spark jobs"],"correct":0,"explanation":"Kinesis Data Firehose is fully managed, buffers, can transform through Lambda, and automatically delivers to S3, Redshift, OpenSearch without consumer code or infrastructure to manage. The KCL on EC2 requires development and instance management. SQS requires a custom consumer. Glue is batch ETL, heavier for simple near-real-time delivery without management."},
  {"id":316,"domain":3,"q":"A big data workload runs large Apache Spark and Hive jobs intermittently. The company wants a managed Hadoop cluster that can scale and use Spot instances to reduce costs, without manually managing the framework installation. Which service should it choose?","options":["Amazon Athena","Amazon EMR","Amazon Redshift Spectrum","AWS Lambda"],"correct":1,"explanation":"Amazon EMR provides a managed Hadoop/Spark cluster, with auto-scaling and Spot instance support to reduce the cost of intermittent jobs, without installing the framework manually. Athena is serverless but limited to ad hoc SQL, not complex Spark/Hive jobs. Redshift Spectrum queries S3 from Redshift but does not run Spark jobs. Lambda has duration/resource limits unsuitable for big data."},
  {"id":317,"domain":3,"q":"A monolithic application processes orders synchronously: order placement waits for payment processing, inventory, and shipping to complete, which creates bottlenecks and limits scalability during spikes. How can you improve scalability and throughput?","options":["Increase the EC2 instance size of the monolith (scale up)","Decouple the steps through an SQS queue and workers that scale independently","Put all requests into a single database transaction","Serve the application through CloudFront to cache the orders"],"correct":1,"explanation":"Decoupling the steps with SQS enables asynchronous processing: order placement publishes a message and the workers consume and scale independently based on load, absorbing spikes and increasing throughput. Vertical scale-up has a limit and remains synchronous. A large transaction worsens the coupling. CloudFront caches static content, not dynamic transactional processing."},
  {"id":318,"domain":3,"q":"An application must upload very large files (several tens of GB) to S3 from clients spread around the world, as quickly and reliably as possible. Which techniques improve the performance and robustness of the upload? (Choose TWO answers.)","multi":true,"options":["Use multipart upload to parallelize and resume parts","Enable S3 Transfer Acceleration to leverage the AWS edge network","Compress then send in a single monolithic PUT request","Serve the uploads through a read-only CloudFront distribution","Disable versioning to speed up writes"],"correct":[0,1],"explanation":"Multipart upload splits the file into parts sent in parallel, with retry of failed parts, improving speed and reliability for large objects. Transfer Acceleration routes the upload through CloudFront edge locations to S3, accelerating long-distance transfers. A monolithic PUT is fragile and slow. CloudFront serves delivery, not uploads. Versioning has no significant impact on write speed."},
  {"id":319,"domain":3,"q":"An existing relational database is reaching its performance and read scalability limits. The company wants a MySQL/PostgreSQL-compatible database offering up to 15 low-latency read replicas sharing the same distributed storage, with high throughput. Which service should you recommend?","options":["Standard Amazon RDS for MySQL with classic Read Replicas","Amazon Aurora with Aurora Replicas","Amazon DynamoDB in on-demand mode","Amazon Redshift"],"correct":1,"explanation":"Aurora uses distributed storage shared between instances, supports up to 15 Aurora Replicas for reads with very low replication latency and throughput up to several times higher than standard MySQL. Classic RDS Read Replicas replicate data per instance (higher latency and limit). DynamoDB is NoSQL, not relational SQL compatible. Redshift is an OLAP analytics warehouse, not a transactional database."},
  {"id":320,"domain":3,"q":"A team is containerizing microservices and wants to run them without managing or sizing servers or EC2 clusters, paying only for the resources consumed per task, with fine-grained automatic scaling. Which compute option should it choose?","options":["Amazon ECS on self-managed EC2 instances","AWS Fargate (with ECS or EKS)","EC2 instances in a cluster placement group","AWS Batch on a managed EC2 Compute Environment"],"correct":1,"explanation":"Fargate is a serverless compute engine for containers: no instances to provision or patch, scaling per task, and billing for the resources consumed by the task. ECS on EC2 requires managing and sizing the instances. A placement group concerns raw EC2. AWS Batch on managed EC2 still involves a layer of instances to size, unlike the pure serverless sought."},
  {"id":321,"domain":3,"q":"A news site serves personalized dynamic pages but also many static resources (CSS, JS, images). The dynamic content varies by user. The team wants to reduce overall latency and the load on the origin. How should it best configure CloudFront?","options":["Disable caching entirely to ensure content freshness","Use distinct cache behaviors: long TTL for static, short/zero TTL with cookie/header forwarding for dynamic","Put all content, static and dynamic, in a single cache behavior with a very long TTL","Serve only static content through CloudFront and expose the origin directly for dynamic content"],"correct":1,"explanation":"Path-based cache behaviors allow a long TTL for static resources (strong caching) and a short or zero TTL with cookie/header forwarding for personalized dynamic content, optimizing latency and origin offload while keeping freshness. Disabling everything removes the caching benefit. A single long TTL would serve stale personalized content. Exposing the origin directly increases latency and load."},
  {"id":322,"domain":3,"q":"A scientific computing application requires a high-performance file system with very high throughput and low latency, optimized for HPC workloads and Lustre-compatible, integrated with S3 for input/output data. Which solution should you choose?","options":["Amazon FSx for Lustre","Amazon EFS in Max I/O mode","Amazon FSx for Windows File Server","An io2 Block Express EBS volume"],"correct":0,"explanation":"FSx for Lustre is a parallel file system designed for HPC and machine learning, offering throughput of hundreds of GB/s and low latency, with native S3 integration. EFS Max I/O scales aggregate throughput but with higher per-operation latency, not optimized for HPC Lustre. FSx for Windows targets SMB/Windows. EBS io2 is single-instance block storage, not a shared parallel file system."},
  {"id":323,"domain":3,"q":"A company stores terabytes of structured analytical data and runs complex aggregation queries over large historical ranges. It wants optimal performance on these OLAP queries using columnar storage and massively parallel execution. Which service is the MOST suitable?","options":["Amazon RDS for PostgreSQL","Amazon DynamoDB","Amazon Redshift","Amazon ElastiCache for Redis"],"correct":2,"explanation":"Redshift is an OLAP data warehouse using columnar storage and a massively parallel (MPP) architecture, optimized for aggregations over large historical volumes. RDS PostgreSQL is row-oriented OLTP, less performant on these massive aggregations. DynamoDB is NoSQL key-value, unsuitable for complex analytical queries. ElastiCache is an in-memory cache, not an analytics warehouse."},
  {"id":324,"domain":3,"q":"An EC2 instance running a network-intensive application (high packet rate, low latency) is not reaching the expected network performance. The team wants to maximize throughput and packets per second at the instance level. Which action is the MOST relevant?","options":["Enable Enhanced Networking (ENA) on an instance type that supports it","Attach multiple Elastic IPs to the instance","Increase the size of the root EBS volume","Enable Multi-AZ for the EC2 instance"],"correct":0,"explanation":"Enhanced Networking through the Elastic Network Adapter (ENA) uses SR-IOV to provide higher throughput, lower latency, and more packets per second on compatible instance types. Adding Elastic IPs does not improve network performance. Enlarging the EBS volume concerns storage, not the network. Multi-AZ relates to availability and does not exist in the strict sense for a single EC2 instance."},
  {"id":325,"domain":3,"q":"A read-intensive application uses DynamoDB and wants to reduce the latency of repeated reads on hot items while optimizing RCU costs, but it also needs strongly consistent reads for certain critical operations. Which approach is correct?","options":["Route all reads, including strongly consistent ones, through DAX to reduce latency","Use DAX for cached eventually consistent reads, and read directly from DynamoDB for strongly consistent reads","Replace DynamoDB with ElastiCache and abandon consistent reads","Enable only the API Gateway query cache for the consistent reads"],"correct":1,"explanation":"DAX accelerates eventually consistent reads and reduces consumed RCUs, but strongly consistent reads are not served from the DAX cache and go directly to DynamoDB. Routing strongly consistent reads through DAX does not guarantee strong consistency. Replacing DynamoDB with ElastiCache loses transactional and consistency guarantees. The API Gateway cache would serve potentially stale data, incompatible with strong consistency."},

  {"id": 401, "domain": 4, "q": "A company has been running a business-critical web application on a fleet of EC2 instances 24/7 for 3 years, with a stable and predictable load. It wants to reduce costs as much as possible while retaining the flexibility to change instance family if necessary during the commitment. Which purchasing option do you recommend?", "options": ["Standard Reserved Instances over 3 years, all upfront payment", "Convertible Reserved Instances over 3 years", "Spot Instances with a Spot Fleet", "On-Demand Instances with Auto Scaling"], "correct": 1, "explanation": "Convertible Reserved Instances allow you to change the family, operating system, or tenancy during the commitment, which meets the need for flexibility while offering a significant discount for a stable load. Standard RIs offer a slightly higher discount but do not allow changing instance family. Spot is not suitable for a permanent critical load because it can be interrupted, and On-Demand is the most expensive option for a continuous load."},
  {"id": 402, "domain": 4, "q": "A data team runs batch video rendering jobs that are tolerant of interruptions and can resume from checkpoints. The jobs run at variable times. Which is the MOST cost-effective purchasing option?", "options": ["On-Demand Instances", "Standard Reserved Instances over 1 year", "Spot Instances", "Dedicated Hosts"], "correct": 2, "explanation": "Spot Instances offer up to 90% discount compared to On-Demand and are perfectly suited to interruption-tolerant workloads with checkpoint-based resumption. Reserved Instances and Savings Plans impose a commitment that is not optimal for an intermittent load, and Dedicated Hosts are the most expensive option, useful only for licensing or compliance constraints."},
  {"id": 403, "domain": 4, "q": "A company anticipates a constant compute spend of about $10/hour for the next 3 years, spread across EC2, Fargate, and Lambda, with families and regions likely to evolve. It wants the maximum discount with full flexibility across these services. What do you recommend?", "options": ["EC2 Instance Savings Plans", "Compute Savings Plans", "Standard Reserved Instances", "Convertible Reserved Instances"], "correct": 1, "explanation": "Compute Savings Plans offer up to 66% discount and apply automatically to EC2, Fargate, and Lambda regardless of region, instance family, or OS, which matches the need for maximum flexibility. EC2 Instance Savings Plans offer a higher discount but are limited to one instance family within a region and do not cover Fargate/Lambda. Reserved Instances cover only EC2."},
  {"id": 404, "domain": 4, "q": "An S3 bucket stores application logs. The logs are frequently accessed for 30 days, then rarely (a few times per year) with a need for immediate access for 60 days, then archived for 7 years with a retrieval time of several hours being acceptable. Which Lifecycle policy minimizes costs?", "options": ["Standard for 30 days, then S3 Standard-IA for 60 days, then Glacier Deep Archive", "Standard for 30 days, then S3 One Zone-IA for 60 days, then Glacier Instant Retrieval", "Standard for 90 days, then Glacier Flexible Retrieval", "Intelligent-Tiering for the entire lifetime"], "correct": 0, "explanation": "S3 Standard-IA is suitable for infrequent but immediate access with high durability, and Glacier Deep Archive is the cheapest class for long-term archiving of 7 years where retrieval in several hours is acceptable. One Zone-IA reduces durability (a single AZ), risky for logs to be retained. Keeping data in Standard for 90 days costs more, and Intelligent-Tiering adds unnecessary monitoring fees when the access patterns are already known."},
  {"id": 405, "domain": 4, "q": "An application stores objects whose access patterns are unpredictable and changing: some objects become inactive then become active again irregularly. The team wants to optimize costs without operational effort or the risk of retrieval fees. Which S3 storage class is the MOST suitable?", "options": ["S3 Standard", "S3 Standard-IA", "S3 Intelligent-Tiering", "S3 One Zone-IA"], "correct": 2, "explanation": "S3 Intelligent-Tiering automatically moves objects between access tiers based on actual patterns with no retrieval fees and no intervention, which is ideal for unpredictable access. Standard-IA and One Zone-IA apply retrieval fees and a minimum charge per object, penalizing objects that become active again. S3 Standard does not reduce costs for objects that have become inactive."},
  {"id": 406, "domain": 4, "q": "EC2 instances in private subnets download large volumes of data from Amazon S3 and DynamoDB. The bill shows high NAT Gateway costs (data processing and transfer). Which solution reduces these costs without compromising security? (Choose TWO answers)", "multi": true, "options": ["Create a Gateway VPC Endpoint for S3", "Create a Gateway VPC Endpoint for DynamoDB", "Move the instances into public subnets with public IPs", "Increase the size of the NAT Gateway", "Replace the NAT Gateway with a larger NAT Instance"], "correct": [0, 1], "explanation": "Gateway VPC Endpoints for S3 and DynamoDB are free and route traffic through the AWS private network, eliminating the passage through the NAT Gateway and its processing/transfer fees. Moving instances into public subnets degrades security, increasing the size of the NAT Gateway does not reduce its cost per GB, and a larger NAT Instance does not remove the cost of traffic to S3/DynamoDB."},
  {"id": 407, "domain": 4, "q": "A company manages multiple AWS accounts through AWS Organizations. Each account purchases its own Reserved Instances separately and each struggles to reach the volume discount threshold. How can it optimize overall costs?", "options": ["Enable consolidated billing to pool usage and share RI/Savings Plans discounts across accounts", "Merge all workloads into a single AWS account", "Ask AWS Support for a manual contractual discount", "Disable Reserved Instances and move everything to On-Demand"], "correct": 0, "explanation": "Consolidated billing in AWS Organizations aggregates the usage of all accounts, which allows volume pricing tiers to be reached faster and automatically shares unused Reserved Instance and Savings Plans discounts across accounts. Merging workloads into a single account breaks isolation and governance, a manual discount is not the standard mechanism, and moving everything to On-Demand increases costs."},
  {"id": 408, "domain": 4, "q": "An architect wants to be proactively alerted when an account's forecasted monthly spend is likely to exceed $5,000, in order to trigger a notification before the overrun. Which service should they use?", "options": ["AWS Cost Explorer", "AWS Cost and Usage Report (CUR)", "AWS Budgets with alerts on the forecast", "AWS Trusted Advisor"], "correct": 2, "explanation": "AWS Budgets lets you define cost budgets and trigger alerts based on actual OR forecasted spend, exactly meeting the need for an alert before an overrun. Cost Explorer is used to analyze and visualize costs after the fact, the CUR provides detailed raw data without native alerting, and Trusted Advisor gives optimization recommendations but not custom budget alerts."},
  {"id": 409, "domain": 4, "q": "A FinOps team wants to identify over-provisioned EC2 instances and obtain right-sizing recommendations based on actual utilization (CPU, memory, network) to reduce costs. Which AWS service provides these recommendations?", "options": ["AWS Compute Optimizer", "AWS Config", "Amazon CloudWatch Logs Insights", "AWS Cost and Usage Report"], "correct": 0, "explanation": "AWS Compute Optimizer analyzes utilization metrics and provides right-sizing recommendations for EC2, Auto Scaling groups, EBS, Lambda, and Fargate. AWS Config tracks configuration compliance but not sizing, CloudWatch Logs Insights analyzes logs and not resource utilization for right-sizing, and the CUR provides billing data without actionable recommendations."},
  {"id": 410, "domain": 4, "q": "A non-production RDS MySQL database is used only during business hours (8 AM-8 PM, Monday to Friday). The team wants to reduce costs during idle periods without deleting the database. Which approach is the MOST effective?", "options": ["Reduce the instance size at night through a script", "Schedule the automatic stop and start of the RDS instance through EventBridge and Lambda outside business hours", "Enable Multi-AZ to reduce costs", "Create a snapshot every evening and delete the instance, then recreate it every morning"], "correct": 1, "explanation": "RDS allows an instance to be stopped for up to 7 days, and scheduling stop/start through EventBridge and Lambda eliminates compute costs during unused hours while preserving the database. Reducing the size does not remove the compute cost. Multi-AZ increases costs. Deleting/recreating from a snapshot is risky, complex, and incurs unnecessary restoration costs/latency."},
  {"id": 411, "domain": 4, "q": "A backend application processes sporadic and unpredictable requests (a few thousand per day, in irregular spikes). It currently runs on a t3.medium EC2 instance permanently, often idle. Which architecture would reduce costs the MOST?", "options": ["Migrate to AWS Lambda with an API Gateway trigger", "Purchase a t3.medium Reserved Instance over 1 year", "Switch to a smaller t3.micro instance On-Demand", "Migrate to an ECS cluster on EC2"], "correct": 0, "explanation": "AWS Lambda bills only for the actual execution time to the millisecond, which is ideal for sporadic and unpredictable loads where the instance remains idle most of the time. A Reserved Instance pays for permanent, largely unused capacity, a smaller instance is still billed 24/7 even when idle, and ECS on EC2 retains the cost of permanent instances."},
  {"id": 412, "domain": 4, "q": "A static website serves images and videos from an S3 bucket to globally distributed users. The data transfer out costs from S3 are high and latency is variable. Which solution reduces transfer costs while improving performance?", "options": ["Enable S3 Transfer Acceleration", "Distribute the content through Amazon CloudFront in front of the S3 bucket", "Replicate the bucket to all AWS regions", "Switch the bucket to S3 One Zone-IA"], "correct": 1, "explanation": "Amazon CloudFront caches content at edge locations close to users, reducing latency and data transfer out from S3 (the transfer from S3 to CloudFront is free), which lowers costs for frequently requested content. S3 Transfer Acceleration optimizes uploads, not delivery. Replicating to all regions is costly and complex, and One Zone-IA does not reduce data transfer out costs."},
  {"id": 413, "domain": 4, "q": "An administrator is reviewing gp2 EBS volumes used by EC2 instances. They find that the default performance is sufficient but want to reduce storage costs by about 20% while keeping equivalent or better performance. What do you recommend?", "options": ["Migrate the volumes from gp2 to gp3", "Migrate the volumes from gp2 to io2", "Migrate the volumes to st1 (throughput-optimized HDD)", "Increase the size of the gp2 volumes to gain IOPS"], "correct": 0, "explanation": "gp3 volumes cost about 20% less per GB than gp2 and offer guaranteed baseline IOPS and throughput independent of size, with the ability to adjust them separately. io2 is more expensive (intended for critical, high-IOPS workloads), st1 is an HDD unsuitable for workloads requiring SSDs, and increasing gp2 size increases the cost."},
  {"id": 414, "domain": 4, "q": "A company has hundreds of EBS snapshots accumulated over the years, many of which correspond to deleted volumes or are obsolete. It wants to reduce snapshot storage costs continuously and automatically. Which solution is the MOST appropriate?", "options": ["Enable encryption on all snapshots", "Set up Data Lifecycle Manager (DLM) policies to manage retention and automatic deletion of snapshots", "Copy all snapshots to S3 Glacier manually", "Convert the snapshots to AMIs"], "correct": 1, "explanation": "Amazon Data Lifecycle Manager automates the creation, retention, and deletion of EBS snapshots based on rules, continuously eliminating obsolete snapshots and reducing costs without manual intervention. Encryption has no effect on costs, copying to Glacier manually is not a native mechanism for EBS snapshots, and converting to AMIs does not eliminate the underlying storage."},
  {"id": 415, "domain": 4, "q": "A database for a development application experiences very intermittent and unpredictable loads, with long periods of no activity followed by sudden spikes. The team wants to avoid paying for a constant baseline capacity. Which database solution minimizes costs?", "options": ["Amazon Aurora Serverless v2", "Amazon RDS with a reserved db.r5.large instance", "Amazon DynamoDB in provisioned capacity mode", "Amazon Redshift"], "correct": 0, "explanation": "Aurora Serverless v2 automatically adjusts capacity (with fine-grained scaling) based on demand and reduces costs during periods of low activity, which suits intermittent and unpredictable loads. A reserved RDS instance pays for fixed constant capacity, DynamoDB in provisioned capacity sets a baseline capacity, and Redshift is an oversized and costly data warehouse for this need."},
  {"id": 416, "domain": 4, "q": "A company wants to analyze its costs in detail at the level of each resource and each tag, export the data to Amazon S3, then query it with Amazon Athena for custom FinOps reports. Which service provides the MOST granular data?", "options": ["AWS Cost Explorer", "AWS Budgets", "AWS Cost and Usage Report (CUR)", "AWS Trusted Advisor"], "correct": 2, "explanation": "The AWS Cost and Usage Report (CUR) provides the most granular billing data (per resource, per tag, hourly), delivers it to an S3 bucket, and integrates natively with Athena/QuickSight for custom analysis. Cost Explorer offers aggregated visualization but not detailed raw export, Budgets is for alerts, and Trusted Advisor gives recommendations without detailed exportable billing data."},
  {"id": 417, "domain": 4, "q": "A containerized application runs on ECS and has a predictable permanent baseline load, supplemented by occasional spikes. The team wants to minimize the container compute costs without managing servers. Which combination is the MOST cost-effective? (Choose TWO answers)", "multi": true, "options": ["Cover the baseline load with a Compute Savings Plan applied to Fargate", "Use Fargate Spot for the interruption-tolerant tasks during spikes", "Provision an oversized On-Demand EC2 cluster to absorb all spikes", "Purchase Standard Reserved Instances for Fargate", "Run all tasks on Fargate On-Demand with no commitment"], "correct": [0, 1], "explanation": "A Compute Savings Plan reduces the cost of the permanent baseline Fargate load through a commitment to hourly spend, and Fargate Spot offers up to 70% discount for interruption-tolerant tasks during spikes. Reserved Instances do not apply to Fargate, an oversized On-Demand EC2 cluster is costly and contrary to serverless, and running everything on Fargate On-Demand with no commitment benefits from no discount."},
  {"id": 418, "domain": 4, "q": "A company stores backups that must be retained for regulatory compliance for 10 years. They will probably never be accessed, but in the event of an audit, retrieval within 12 hours is acceptable. Which storage class minimizes costs?", "options": ["S3 Glacier Instant Retrieval", "S3 Glacier Flexible Retrieval", "S3 Glacier Deep Archive", "S3 Standard-IA"], "correct": 2, "explanation": "S3 Glacier Deep Archive is the cheapest AWS storage class, designed for rarely accessed long-term archiving with acceptable 12-hour (standard) retrieval times, which perfectly matches a 10-year compliance retention. Glacier Instant Retrieval costs more for immediate access not required here, Glacier Flexible Retrieval is more expensive than Deep Archive, and Standard-IA is far too costly for data that is almost never accessed."},
  {"id": 419, "domain": 4, "q": "A software licensing workload requires physical hardware-level isolation and visibility into the sockets/cores to comply with an existing 'Bring Your Own License' license tied to the physical server. The company wants to minimize costs while respecting this constraint. Which EC2 purchasing option is appropriate?", "options": ["Dedicated Hosts with a commitment (Reserved)", "Dedicated Instances", "Spot Instances", "Shared tenancy On-Demand Instances"], "correct": 0, "explanation": "Dedicated Hosts provide a dedicated physical server with visibility into sockets and cores, required for BYOL licenses tied to the physical hardware, and a reserved commitment (Dedicated Host Reservation) reduces the cost. Dedicated Instances isolate at the hardware level but do not expose the sockets/cores for BYOL, Spot is not suitable for a stable licensed workload, and shared tenancy does not meet the physical isolation requirement."},
  {"id": 420, "domain": 4, "q": "A small business has deployed several environments and suspects there are unused resources (unattached Elastic IPs, load balancers with no targets, unattached EBS volumes) generating unnecessary costs. Which AWS service helps quickly identify this waste with cost optimization recommendations?", "options": ["AWS Trusted Advisor (Cost Optimization checks)", "AWS CloudTrail", "Amazon Inspector", "AWS Systems Manager Inventory"], "correct": 0, "explanation": "AWS Trusted Advisor includes a Cost Optimization category that detects underutilized or unused resources such as unattached Elastic IPs, idle load balancers, and underutilized EBS volumes, with direct recommendations. CloudTrail logs API calls, Amazon Inspector assesses security/vulnerabilities, and Systems Manager Inventory catalogs configurations without cost analysis."}
);
